INSERT INTO `wp_aioseo_notifications` VALUES
(1,'69725ef743934',NULL,'Have you connected your site to Google Search Console?','AIOSEO can now verify whether your site is correctly verified with Google Search Console and that your sitemaps have been submitted correctly. Connect with Google Search Console now to ensure your content is being added to Google as soon as possible for increased rankings.','warning','[\"all\"]',NULL,'search-console-site-not-connected','2026-01-22 17:31:35',NULL,'Connect to Google Search Console','https://route#aioseo-settings&aioseo-scroll=google-search-console-settings&aioseo-highlight=google-search-console-settings:webmaster-tools?activetool=googleSearchConsole',NULL,NULL,0,0,'2026-01-22 17:31:35','2026-01-22 17:31:35'),
(2,'6984dd449f130',NULL,'Email Reports','Stay ahead in SEO with our new email digest! Get the latest tips, trends, and tools delivered right to your inbox, helping you optimize smarter and faster. Enable it today and never miss an update that can take your rankings to the next level.','info','[\"all\"]',NULL,'email-reports-enable-reminder','2026-02-05 18:11:16',NULL,'Enable Email Reports','https://route#aioseo-settings&aioseo-scroll=aioseo-email-summary-row&aioseo-highlight=aioseo-email-summary-row:advanced','All Good, I\'m already getting it','http://action#notification/email-reports-enable',0,1,'2026-02-05 18:11:16','2026-02-05 18:11:16');
